import { inngest } from "./inngest/client";
import { USER_CREATED_EVENT } from "./inngest/functions";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function createUser(input: {
  email: string;
  name: string;
}): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedule the "10 minutes later" reminder job. This just enqueues the
  // event — Inngest owns the delay/retry logic in src/lib/inngest/functions.ts.
  await inngest.send({
    name: USER_CREATED_EVENT,
    data: {
      userId: user.id,
      email: user.email,
      name: user.name,
      createdAt: user.createdAt,
    },
  });

  return user;
}

